mapper.update:
UPDATE fin_ex_chat_interaction_request_t
SET status = 'RESPONDING',
    continue_run_id = #{continueRunId},
    response_payload_json = #{responsePayloadJson},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'WAITING'
  AND (expires_at IS NULL OR expires_at > #{now})

UPDATE fin_ex_chat_interaction_request_t
SET status = 'ANSWERED',
    answered_at = #{answeredAt},
    updated_at = #{answeredAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'RESPONDING'

UPDATE fin_ex_chat_interaction_request_t
SET status = 'ANSWERED',
    answered_at = #{answeredAt},
    updated_at = #{answeredAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'RESPONDING'
  AND continue_run_id = #{continueRunId}

UPDATE fin_ex_chat_interaction_request_t
SET status = 'WAITING',
    continue_run_id = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'RESPONDING'

UPDATE fin_ex_chat_interaction_request_t
SET status = 'WAITING',
    continue_run_id = NULL,
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'RESPONDING'
  AND continue_run_id = #{continueRunId}

UPDATE fin_ex_chat_interaction_request_t
SET status = 'CANCELLED',
    cancelled_at = #{cancelledAt},
    updated_at = #{cancelledAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND status IN ('WAITING', 'RESPONDING')

UPDATE fin_ex_chat_interaction_request_t
SET status = 'CANCELLED',
    cancelled_at = #{cancelledAt},
    updated_at = #{cancelledAt}
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'WAITING'

UPDATE fin_ex_chat_interaction_request_t
SET status = 'EXPIRED',
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{interactionId}
  AND status = 'WAITING'
